  3	import com.fasterxml.jackson.databind.ObjectMapper;
  4	import com.fasterxml.jackson.databind.SerializationFeature;
  5	import com.fasterxml.jackson.datatype.jsr310.JavaTimeModule;
  6	import com.pousada.maralta.controller.ApiController;
  7	import com.pousada.maralta.infrastructure.DatabaseConfig;
  8	import com.pousada.maralta.repository.*;
  9	import com.pousada.maralta.service.ReportService;
 10	import com.pousada.maralta.service.ReservationService;
 11	import io.javalin.Javalin;
 12	import io.javalin.json.JavalinJackson;
 13	
 14	public class Application {
 15	    public static void main(String[] args) {
 16	        DatabaseConfig.initialize();
 17	
 18	        ReservationRepository reservationRepository = new JdbcReservationRepository();
 19	        RoomRepository roomRepository = new JdbcRoomRepository();
 20	        MessageRepository messageRepository = new JdbcMessageRepository();
 21	
 22	        ReservationService reservationService = new ReservationService(
 23	            reservationRepository, roomRepository, messageRepository
 24	        );
 25	
 26	        ReportService reportService = new ReportService(reservationRepository, roomRepository);
 27	
 28	        ApiController apiController = new ApiController(
 29	            reservationService, reportService, roomRepository, messageRepository
 30	        );
 31	
 32	        ObjectMapper objectMapper = new ObjectMapper();
 33	        objectMapper.registerModule(new JavaTimeModule());
 34	        objectMapper.disable(SerializationFeature.WRITE_DATES_AS_TIMESTAMPS);
 35	
 36	        int port = Integer.parseInt(System.getenv().getOrDefault("PORT", "7070"));
 37	
 38	        Javalin app = Javalin.create(config -> {
 39	            config.jsonMapper(new JavalinJackson(objectMapper, true));
 40	        }).start(port);
 41	
 42	        apiController.registerRoutes(app);
 43	
 44	        Runtime.getRuntime().addShutdownHook(new Thread(() -> {
 45	            app.stop();
 46	            DatabaseConfig.shutdown();
 47	        }));
 48	    }
 49	}
 50	package com.pousada.maralta.controller;
 51	
 52	import com.pousada.maralta.controller.dto.*;
 53	import com.pousada.maralta.domain.*;
 54	import com.pousada.maralta.repository.MessageRepository;
 55	import com.pousada.maralta.repository.ReservationRepository;
 56	import com.pousada.maralta.repository.RoomRepository;
 57	import com.pousada.maralta.service.ReportService;
 58	import com.pousada.maralta.service.ReservationService;
 59	import io.javalin.Javalin;
 60	import io.javalin.http.Context;
 61	
 62	import java.time.LocalDate;
 63	import java.time.YearMonth;
 64	import java.time.format.DateTimeFormatter;
 65	import java.time.format.DateTimeParseException;
 66	import java.util.List;
 67	
 68	import static com.pousada.maralta.service.ReservationService.*;
 69	
 70	public class ApiController {
 71	    private final ReservationService reservationService;
 72	    private final ReportService reportService;
 73	    private final RoomRepository roomRepository;
 74	    private final MessageRepository messageRepository;
 75	
 76	    public ApiController(ReservationService reservationService,
 77	                        ReportService reportService,
 78	                        RoomRepository roomRepository,
 79	                        MessageRepository messageRepository) {
 80	        this.reservationService = reservationService;
 81	        this.reportService = reportService;
 82	        this.roomRepository = roomRepository;
 83	        this.messageRepository = messageRepository;
 84	    }
 85	
 86	    public void registerRoutes(Javalin app) {
 87	        app.get("/rooms", this::getRooms);
 88	        app.post("/reservations", this::createReservation);
 89	        app.get("/reservations/{id}", this::getReservation);
 90	        app.post("/reservations/{id}/confirmation", this::confirmReservation);
 91	        app.post("/reservations/{id}/cancellation", this::cancelReservation);
 92	        app.post("/reservations/{id}/check-in", this::checkIn);
 93	        app.post("/reservations/{id}/check-out", this::checkOut);
 94	        app.get("/reservations/{id}/document", this::getDocument);
 95	        app.get("/messages", this::getMessages);
 96	        app.get("/reports/occupancy", this::getOccupancyReport);
 97	        app.get("/reports/revenue", this::getRevenueReport);
 98	
 99	        app.exception(RoomNotFoundException.class, (e, ctx) ->
100	            ctx.status(404).json(new ErrorResponse("ROOM_NOT_FOUND", "Room not found")));
101	        app.exception(ReservationNotFoundException.class, (e, ctx) ->
102	            ctx.status(404).json(new ErrorResponse("RESERVATION_NOT_FOUND", "Reservation not found")));
103	        app.exception(RoomUnavailableException.class, (e, ctx) ->
104	            ctx.status(409).json(new ErrorResponse("ROOM_UNAVAILABLE", "Room is not available for the selected dates")));
105	        app.exception(OperationNotAllowedException.class, (e, ctx) ->
106	            ctx.status(409).json(new ErrorResponse("OPERATION_NOT_ALLOWED", "Operation not allowed in current reservation status")));
107	        app.exception(CapacityExceededException.class, (e, ctx) ->
108	            ctx.status(422).json(new ErrorResponse("CAPACITY_EXCEEDED", "Number of guests exceeds room capacity")));
109	        app.exception(InvalidRequestException.class, (e, ctx) ->
110	            ctx.status(400).json(new ErrorResponse("INVALID_REQUEST", e.getMessage())));
111	    }
112	
113	    private void getRooms(Context ctx) {
114	        List<Room> rooms = roomRepository.findAll();
115	        ctx.json(rooms.stream().map(RoomResponse::from).toList());
116	    }
117	
118	    private void createReservation(Context ctx) {
119	        CreateReservationRequest request;
120	        try {
121	            request = ctx.bodyAsClass(CreateReservationRequest.class);
122	        } catch (Exception e) {
123	            throw new InvalidRequestException("Invalid JSON body");
124	        }
125	
126	        validateRequest(request);
127	
128	        GuestIdentification identification = parseIdentification(request);
129	        RatePlan ratePlan;
130	        try {
131	            ratePlan = RatePlan.valueOf(request.ratePlan());
132	        } catch (Exception e) {
133	            throw new InvalidRequestException("Invalid rate plan");
134	        }
135	
136	        Reservation reservation = reservationService.createReservation(
137	            request.roomNumber(),
138	            request.guestName(),
139	            request.guestEmail(),
140	            identification,
141	            request.checkIn(),
142	            request.checkOut(),
143	            request.guests(),
144	            ratePlan
145	        );
146	
147	        ctx.status(201).json(ReservationResponse.from(reservation));
148	    }
149	
150	    private void getReservation(Context ctx) {
151	        long id = Long.parseLong(ctx.pathParam("id"));
152	        Reservation reservation = reservationService.getReservation(id);
153	        ctx.json(ReservationResponse.from(reservation));
154	    }
155	
156	    private void confirmReservation(Context ctx) {
157	        long id = Long.parseLong(ctx.pathParam("id"));
158	        Reservation reservation = reservationService.confirmReservation(id);
159	        ctx.json(ReservationResponse.from(reservation));
160	    }
161	
162	    private void cancelReservation(Context ctx) {
163	        long id = Long.parseLong(ctx.pathParam("id"));
164	        Reservation reservation = reservationService.cancelReservation(id);
165	        ctx.json(ReservationResponse.from(reservation));
166	    }
167	
168	    private void checkIn(Context ctx) {
169	        long id = Long.parseLong(ctx.pathParam("id"));
170	        Reservation reservation = reservationService.checkIn(id);
171	        ctx.json(ReservationResponse.from(reservation));
172	    }
173	
174	    private void checkOut(Context ctx) {
175	        long id = Long.parseLong(ctx.pathParam("id"));
176	        ReservationDocument document = reservationService.checkOut(id);
177	        ctx.json(DocumentResponse.from(document));
178	    }
179	
180	    private void getDocument(Context ctx) {
181	        long id = Long.parseLong(ctx.pathParam("id"));
182	        ReservationDocument document = reservationService.getDocument(id);
183	        ctx.json(DocumentResponse.from(document));
184	    }
185	
186	    private void getMessages(Context ctx) {
187	        List<Message> messages = messageRepository.findAll();
188	        ctx.json(messages.stream().map(MessageResponse::from).toList());
189	    }
190	
191	    private void getOccupancyReport(Context ctx) {
192	        String dateStr = ctx.queryParam("date");
193	        if (dateStr == null) {
194	            throw new InvalidRequestException("Missing date parameter");
195	        }
196	
197	        LocalDate date;
198	        try {
199	            date = LocalDate.parse(dateStr, DateTimeFormatter.ISO_LOCAL_DATE);
200	        } catch (DateTimeParseException e) {
201	            throw new InvalidRequestException("Invalid date format");
202	        }
203	
204	        String csv = reportService.generateOccupancyReport(date);
205	        ctx.contentType("text/csv; charset=utf-8").result(csv);
206	    }
207	
208	    private void getRevenueReport(Context ctx) {
209	        String monthStr = ctx.queryParam("month");
210	        if (monthStr == null) {
211	            throw new InvalidRequestException("Missing month parameter");
212	        }
213	
214	        YearMonth month;
215	        try {
216	            month = YearMonth.parse(monthStr, DateTimeFormatter.ofPattern("yyyy-MM"));
217	        } catch (DateTimeParseException e) {
218	            throw new InvalidRequestException("Invalid month format");
219	        }
220	
221	        String csv = reportService.generateRevenueReport(month);
222	        ctx.contentType("text/csv; charset=utf-8").result(csv);
223	    }
224	
225	    private void validateRequest(CreateReservationRequest request) {
226	        if (request.roomNumber() == null || request.guestName() == null ||
227	            request.guestEmail() == null || request.checkIn() == null ||
228	            request.checkOut() == null || request.guests() == null ||
229	            request.ratePlan() == null) {
230	            throw new InvalidRequestException("Missing required fields");
231	        }
232	
233	        if (request.checkOut().isBefore(request.checkIn()) ||
234	            request.checkOut().equals(request.checkIn())) {
235	            throw new InvalidRequestException("Check-out must be after check-in");
236	        }
237	
238	        if (request.guests() < 1) {
239	            throw new InvalidRequestException("At least one guest is required");
240	        }
241	    }
242	
243	    private GuestIdentification parseIdentification(CreateReservationRequest request) {
244	        boolean hasCpf = request.guestCpf() != null;
245	        boolean hasCnpj = request.companyCnpj() != null || request.companyName() != null;
246	        boolean hasPassport = request.guestPassport() != null || request.guestCountry() != null;
247	
248	        int count = (hasCpf ? 1 : 0) + (hasCnpj ? 1 : 0) + (hasPassport ? 1 : 0);
249	
250	        if (count != 1) {
251	            throw new InvalidRequestException(
252	                "Exactly one identification method required: guestCpf, or (companyCnpj + companyName), or (guestPassport + guestCountry)"
253	            );
254	        }
255	
256	        if (hasCpf) {
257	            return new CpfIdentification(request.guestCpf());
258	        } else if (hasCnpj) {
259	            if (request.companyCnpj() == null || request.companyName() == null) {
260	                throw new InvalidRequestException("Both companyCnpj and companyName are required");
261	            }
262	            return new CnpjIdentification(request.companyCnpj(), request.companyName());
263	        } else {
264	            if (request.guestPassport() == null || request.guestCountry() == null) {
265	                throw new InvalidRequestException("Both guestPassport and guestCountry are required");
266	            }
267	            return new PassportIdentification(request.guestPassport(), request.guestCountry());
268	        }
269	    }
270	
271	    public static class InvalidRequestException extends RuntimeException {
272	        public InvalidRequestException(String message) {
273	            super(message);
274	        }
275	    }
276	}

