  1	package com.pousada.maralta.service;
  2	
  3	import com.pousada.maralta.domain.*;
  4	import com.pousada.maralta.repository.MessageRepository;
  5	import com.pousada.maralta.repository.ReservationRepository;
  6	import com.pousada.maralta.repository.RoomRepository;
  7	
  8	import java.time.LocalDate;
  9	import java.time.temporal.ChronoUnit;
 10	import java.util.List;
 11	
 12	public class ReservationService {
 13	    private final ReservationRepository reservationRepository;
 14	    private final RoomRepository roomRepository;
 15	    private final MessageRepository messageRepository;
 16	    private final PricingService pricingService;
 17	    private final DocumentGenerator documentGenerator;
 18	    private final EmailService emailService;
 19	
 20	    public ReservationService(ReservationRepository reservationRepository,
 21	                            RoomRepository roomRepository,
 22	                            MessageRepository messageRepository) {
 23	        this.reservationRepository = reservationRepository;
 24	        this.roomRepository = roomRepository;
 25	        this.messageRepository = messageRepository;
 26	        this.pricingService = new PricingService();
 27	        this.documentGenerator = new DocumentGenerator();
 28	        this.emailService = new EmailService();
 29	    }
 30	
 31	    public Reservation createReservation(String roomNumber, String guestName, String guestEmail,
 32	                                        GuestIdentification identification, LocalDate checkIn,
 33	                                        LocalDate checkOut, int guests, RatePlan ratePlan) {
 34	        Room room = roomRepository.findByNumber(roomNumber)
 35	            .orElseThrow(() -> new RoomNotFoundException());
 36	
 37	        if (guests < 1 || guests > room.capacity()) {
 38	            throw new CapacityExceededException();
 39	        }
 40	
 41	        int nights = (int) ChronoUnit.DAYS.between(checkIn, checkOut);
 42	
 43	        LocalDate current = checkIn;
 44	        while (current.isBefore(checkOut)) {
 45	            List<Reservation> conflicts = reservationRepository.findByRoomAndNight(roomNumber, current);
 46	            if (!conflicts.isEmpty()) {
 47	                throw new RoomUnavailableException();
 48	            }
 49	            current = current.plusDays(1);
