161	public class PricingService {
162	    private static final BigDecimal HIGH_SEASON_MULTIPLIER = new BigDecimal("1.20");
163	    private static final BigDecimal NON_REFUNDABLE_DISCOUNT = new BigDecimal("0.15");
164	
165	    public BigDecimal calculateNightPrice(RoomType roomType, LocalDate night) {
166	        BigDecimal basePrice = roomType.getNightlyRate();
167	        if (isHighSeason(night)) {
168	            basePrice = basePrice.multiply(HIGH_SEASON_MULTIPLIER);
169	        }
170	        return round(basePrice);
171	    }
172	
173	    public BigDecimal calculateSubtotal(RoomType roomType, LocalDate checkIn, LocalDate checkOut) {
174	        BigDecimal total = BigDecimal.ZERO;
175	        LocalDate current = checkIn;
176	        while (current.isBefore(checkOut)) {
177	            total = total.add(calculateNightPrice(roomType, current));
178	            current = current.plusDays(1);
179	        }
180	        return round(total);
181	    }
