183	    public BigDecimal calculateDiscount(BigDecimal subtotal, RatePlan ratePlan) {
184	        if (ratePlan == RatePlan.NON_REFUNDABLE) {
185	            return round(subtotal.multiply(NON_REFUNDABLE_DISCOUNT));
186	        }
187	        return BigDecimal.ZERO;
188	    }
