194	    private boolean isHighSeason(LocalDate date) {
195	        Month month = date.getMonth();
196	        int day = date.getDayOfMonth();
197	
198	        if (month == Month.DECEMBER && day >= 15) {
199	            return true;
200	        }
201	
202	        if (month == Month.JANUARY || month == Month.FEBRUARY) {
203	            return true;
204	        }
205	
206	        if (month == Month.JULY) {
207	            return true;
208	        }
209	
210	        return false;
211	    }
