  1	package com.pousada.maralta.infrastructure;
  2	
  3	import com.zaxxer.hikari.HikariConfig;
  4	import com.zaxxer.hikari.HikariDataSource;
  5	
  6	import javax.sql.DataSource;
  7	import java.sql.Connection;
  8	import java.sql.SQLException;
  9	import java.sql.Statement;
 10	
 11	public class DatabaseConfig {
 12	    private static HikariDataSource dataSource;
 13	
 14	    public static void initialize() {
 15	        String url = System.getenv().getOrDefault("DB_URL", "jdbc:postgresql://localhost:5432/maralta");
 16	        String user = System.getenv().getOrDefault("DB_USER", "postgres");
 17	        String password = System.getenv().getOrDefault("DB_PASSWORD", "postgres");
 18	
 19	        HikariConfig config = new HikariConfig();
 20	        config.setJdbcUrl(url);
 21	        config.setUsername(user);
 22	        config.setPassword(password);
 23	        config.setMaximumPoolSize(10);
 24	
 25	        dataSource = new HikariDataSource(config);
 26	
 27	        createTables();
 28	    }
 29	
 30	    public static DataSource getDataSource() {
 31	        return dataSource;
 32	    }
 33	
 34	    public static void shutdown() {
 35	        if (dataSource != null) {
 36	            dataSource.close();
 37	        }
 38	    }
 39	
 40	    private static void createTables() {
 41	        try (Connection conn = dataSource.getConnection();
 42	             Statement stmt = conn.createStatement()) {
 43	
 44	            stmt.execute("""
 45	                CREATE TABLE IF NOT EXISTS rooms (
 46	                    number VARCHAR(10) PRIMARY KEY,
 47	                    type VARCHAR(20) NOT NULL
 48	                )
 49	            """);
 50	
 51	            stmt.execute("""
 52	                CREATE TABLE IF NOT EXISTS reservations (
 53	                    id BIGSERIAL PRIMARY KEY,
 54	                    room_number VARCHAR(10) NOT NULL,
 55	                    guest_name VARCHAR(255) NOT NULL,
 56	                    guest_email VARCHAR(255) NOT NULL,
 57	                    guest_cpf VARCHAR(14),
 58	                    company_cnpj VARCHAR(18),
 59	                    company_name VARCHAR(255),
 60	                    guest_passport VARCHAR(50),
 61	                    guest_country VARCHAR(100),
 62	                    check_in DATE NOT NULL,
 63	                    check_out DATE NOT NULL,
 64	                    guests INTEGER NOT NULL,
 65	                    rate_plan VARCHAR(20) NOT NULL,
 66	                    nights INTEGER NOT NULL,
 67	                    subtotal DECIMAL(10, 2) NOT NULL,
 68	                    discount DECIMAL(10, 2) NOT NULL,
 69	                    total DECIMAL(10, 2) NOT NULL,
 70	                    status VARCHAR(20) NOT NULL,
 71	                    amount_paid DECIMAL(10, 2) NOT NULL DEFAULT 0,
 72	                    refund DECIMAL(10, 2)
 73	                )
 74	            """);
 75	
 76	            stmt.execute("""
 77	                CREATE TABLE IF NOT EXISTS messages (
 78	                    id BIGSERIAL PRIMARY KEY,
 79	                    channel VARCHAR(20) NOT NULL,
 80	                    recipient VARCHAR(255) NOT NULL,
 81	                    subject VARCHAR(255) NOT NULL,
 82	                    body TEXT NOT NULL
 83	                )
 84	            """);
 85	
 86	            initializeRooms(conn);
 87	
 88	        } catch (SQLException e) {
 89	            throw new RuntimeException("Failed to create tables", e);
 90	        }
 91	    }
 92	
 93	    private static void initializeRooms(Connection conn) throws SQLException {
 94	        try (Statement stmt = conn.createStatement()) {
 95	            stmt.execute("INSERT INTO rooms (number, type) VALUES ('101', 'STANDARD') ON CONFLICT DO NOTHING");
 96	            stmt.execute("INSERT INTO rooms (number, type) VALUES ('102', 'STANDARD') ON CONFLICT DO NOTHING");
 97	            stmt.execute("INSERT INTO rooms (number, type) VALUES ('201', 'DELUXE') ON CONFLICT DO NOTHING");
 98	            stmt.execute("INSERT INTO rooms (number, type) VALUES ('202', 'DELUXE') ON CONFLICT DO NOTHING");
 99	            stmt.execute("INSERT INTO rooms (number, type) VALUES ('301', 'SUITE') ON CONFLICT DO NOTHING");
100	        }
101	    }
102	}
