104	
105	import com.pousada.maralta.domain.*;
106	import com.pousada.maralta.infrastructure.DatabaseConfig;
107	
108	import java.math.BigDecimal;
109	import java.sql.*;
110	import java.time.LocalDate;
111	import java.time.YearMonth;
112	import java.util.ArrayList;
113	import java.util.List;
114	import java.util.Optional;
115	
116	public class JdbcReservationRepository implements ReservationRepository {
117	    @Override
118	    public Reservation save(Reservation reservation) {
119	        if (reservation.getId() == null) {
120	            return insert(reservation);
121	        } else {
122	            return update(reservation);
123	        }
124	    }
125	
126	    private Reservation insert(Reservation reservation) {
127	        String sql = """
128	            INSERT INTO reservations (
129	                room_number, guest_name, guest_email, guest_cpf, company_cnpj, company_name,
130	                guest_passport, guest_country, check_in, check_out, guests, rate_plan,
131	                nights, subtotal, discount, total, status, amount_paid, refund
132	            ) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)
133	        """;
134	
135	        try (Connection conn = DatabaseConfig.getDataSource().getConnection();
136	             PreparedStatement stmt = conn.prepareStatement(sql, Statement.RETURN_GENERATED_KEYS)) {
137	
138	            setReservationParameters(stmt, reservation);
139	            stmt.executeUpdate();
140	
141	            try (ResultSet rs = stmt.getGeneratedKeys()) {
142	                if (rs.next()) {
143	                    reservation.setId(rs.getLong(1));
144	                }
145	            }
146	
147	            return reservation;
148	        } catch (SQLException e) {
149	            throw new RuntimeException("Failed to insert reservation", e);
150	        }
151	    }
152	
153	    private Reservation update(Reservation reservation) {
154	        String sql = """
155	            UPDATE reservations SET
156	                room_number = ?, guest_name = ?, guest_email = ?, guest_cpf = ?,
157	                company_cnpj = ?, company_name = ?, guest_passport = ?, guest_country = ?,
158	                check_in = ?, check_out = ?, guests = ?, rate_plan = ?,
159	                nights = ?, subtotal = ?, discount = ?, total = ?, status = ?,
160	                amount_paid = ?, refund = ?
161	            WHERE id = ?
162	        """;
163	
164	        try (Connection conn = DatabaseConfig.getDataSource().getConnection();
165	             PreparedStatement stmt = conn.prepareStatement(sql)) {
166	
167	            setReservationParameters(stmt, reservation);
168	            stmt.setLong(20, reservation.getId());
169	            stmt.executeUpdate();
170	
171	            return reservation;
172	        } catch (SQLException e) {
173	            throw new RuntimeException("Failed to update reservation", e);
174	        }
175	    }
176	
177	    @Override
178	    public Optional<Reservation> findById(Long id) {
179	        String sql = "SELECT * FROM reservations WHERE id = ?";
180	
